import React, { useEffect, useState } from 'react';
import { getAccessToken } from '../services/spotifyAuth';

const WebPlayer = ({ trackUri }) => {
  const [player, setPlayer] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);

  // Load the Spotify Web Playback SDK script dynamically
  useEffect(() => {
    const loadSpotifySDK = () => {
      const script = document.createElement('script');
      script.src = 'https://sdk.scdn.co/spotify-player.js';
      script.async = true;
      script.onload = () => initializePlayer();
      document.body.appendChild(script);
    };

    const initializePlayer = () => {
      const token = getAccessToken(); // Get your stored access token

      if (window.Spotify) {
        const player = new window.Spotify.Player({
          name: 'Track Similarity Player',
          getOAuthToken: (cb) => {
            cb(token);
          },
          volume: 0.5,
        });

        setPlayer(player);

        // Connect to the player
        player.connect();

        // Event listeners for the player
        player.addListener('ready', ({ device_id }) => {
          console.log('Ready with Device ID', device_id);
        });

        player.addListener('not_ready', ({ device_id }) => {
          console.log('Device ID has gone offline', device_id);
        });
      }
    };

    // Load the Spotify SDK script if it's not already loaded
    if (!window.Spotify) {
      loadSpotifySDK();
    } else {
      initializePlayer();
    }
  }, []);

  // Play the selected track only when the user clicks the "Play" button
  const handlePlay = async () => {
    if (player && trackUri) {
      try {
        // Activate the playback only after a user gesture
        await player.activateElement();
        setIsPlaying(true);
      } catch (error) {
        console.error('Error starting playback:', error);
      }
    }
  };

  return (
    <div>
      <h2>Now Playing</h2>
      {trackUri ? (
        <>
          <p>Track URI: {trackUri}</p>
          <button onClick={handlePlay}>{isPlaying ? 'Playing...' : 'Play Track'}</button>
        </>
      ) : (
        <p>Select a track to play</p>
      )}
    </div>
  );
};

export default WebPlayer;
